head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.spanYN = "N"; //기업인수목적 회사 구분
scwin.vScrenID = "ULDSTF05206.xml";
scwin.strCbd_MF = "(null)^선택해주세요,0^매매거래정지 지정,2^매매거래정지 및 정지해제";
scwin.bndYN = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //채권상장법인 구분
scwin.fn_search = function() {
    var url = "/tradingSuspension.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + txb_IsurCd.getValue() + "&GUBUN_CD=STK";
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};



// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    scwin.fn_search();
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts_List.getCellData(dts_List.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = scwin.spanYN; //기업인수목적회사 구분_2010.05.30
    arrPar[7] = dts_List.getCellData(dts_List.getRowPosition(), "BND_LIST_CORP_YN"); //채권상장법인 구분
    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    /*if(cmb_RegistTyp.BindColVal == "2" || cmb_RegistTyp.BindColVal == "4" || 
       cmb_RegistTyp.BindColVal == "5" || cmb_RegistTyp.BindColVal == "6" || cmb_RegistTyp.BindColVal == "7")
    {
    	arrPar[5] = "2"; // 2 정지 및 해제 
    } else {
    	arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    }*/
    arrPar[5] = cmb_RegistTyp.BindColVal;
    arrPar[6] = scwin.spanYN; //기업인수목적회사 구분_2010.05.30
    arrPar[7] = scwin.bndYN; //채권상장법인 구분

};
scwin.fn_newpre_create_frame = async function(arg, startDd) {
    if (arg == "1" && startDd != "") arg = "3";

    //기업인수목적 회사 추가로 인한 변경 2010.05.30
    if (scwin.spanYN == "N") {
        //0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제 
        //4:매매거래정지 및 정지해제(중요내용공시)       99808,
        //5:매매거래정지 및 정지해제(풍문 등 조회공시) 99810
        //6:매매거래정지 및 정지해제(불성실공시)          99807
        //7:매매거래정지 및 정지해제(우회상장심사)      99834
        switch (arg) {
            case "0": // HALT_DESNRELS_TP_CD 0 정지 
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_AGN", "../lstproc/ULDSTF05207.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정", 200, 200, 660, 455 + 35, "window");
                break;
            case "2": // HALT_DESNRELS_TP_CD 2 정지 및 해제
                //frame.CreateDialogFrame("DLG_TRDSUSP_ANT","../lstproc/ULDSTF05209.gfm", fn_getSecuGrpNm(fr_SecuGrpId) +  " 매매거래정지 지정 및 해제", 200, 200, 650 , 450+35, "window"); 

                if (scwin.fr_SecuGrpId == 'MF') {
                    // by nhkw 20181116
                    await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05209.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제", 200, 200, 650, 450 + 35, "window");
                } else {
                    await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05209.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제(상장규정)", 200, 200, 650, 450 + 35, "window");
                }
                break;
            case "3":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../lstproc/ULDSTF05925.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제", 200, 200, 650, 555 + 35, "window");
                break;
            case "4":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05228.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(불성실공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "5":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05229.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(중요내용공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "6":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05230.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(풍문 등 조회공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "7":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05231.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(우회상장심사)", 200, 200, 700, 500 + 35, "window");
                break;
        }
    } else {
        switch (arg) {
            case "0":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_AGN", "../lstproc/ULDSTF05207.gfm", "SPAC  매매거래정지 지정", 200, 200, 650, 450 + 30, "window");
                break;
            case "2":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05209.gfm", "SPAC 매매거래정지 지정 및 해제", 200, 200, 650, 450 + 35, "window");
                break;
            case "3":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../lstproc/ULDSTF05925.gfm", "SPAC 매매거래정지 해제", 200, 200, 650, 555 + 35, "window");
                break;
            case "4":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05228.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "SPAC 매매거래정지 및 정지해제(불성실공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "5":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05229.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "SPAC 매매거래정지 및 정지해제(중요내용공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "6":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05230.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "SPAC 매매거래정지 및 정지해제(풍문 등 조회공시)", 200, 200, 700, 500 + 35, "window");
                break;
            case "7":
                await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05231.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "SPAC 매매거래정지 및 정지해제(우회상장심사)", 200, 200, 700, 500 + 35, "window");
                break;
        }
    }

    //fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.
    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.fn_bnd_list_corp_yn = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ISUR_INFO_INST";
    url += "&queryId=lds.stf.lstproc.select.isBndListStat";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}ISUR_CD=" + txb_IsurCd.getValue();
    dts_Corp.DataID = encodeURI(url);
    dts_Corp.Reset();
    return dts_Corp.getCellData(1, "BND_LIST_CORP_YN");
};
scwin.fn_direct_dlscls_status = function() {
    if (scwin.fn_accessRights()) scwin.fn_direct_dlscls_onoff();
};
scwin.fn_accessRights = function() {
    if ((js_dep_cd == "2600" && js_jobtitl == "40") || //유가공시부&부서장
        (js_dep_cd == "2610" && js_jobtitl == "09") || //유가공시제도팀&팀장
        js_dep_cd == "ZSYS") {
        $c.stf.showObj(panel_accessRights, true);
        return true;
    } else {
        $c.stf.showObj(panel_accessRights, false);
        return false;
    }
};
scwin.fn_direct_dlscls_onoff = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SVC_STAT_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.common.select.svcstat" + "&{P}param01=ETC19";
    dts_Svcstat.DataID = encodeURI(url);
    dts_Svcstat.reset();
};
scwin.fn_save_direct_dlscls_onoff = function() {
    var url = "/tradingSuspension.do?method=updateSvcStat";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_process.Action = $c.lc.fn_encodeNSession(url);
    trs_process.KeyName = "toinb_dataid4";
    trs_process.KeyValue = "JSP(I:pInput=dts_Svcstat)";
    trs_process.Post();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "매매거래정지내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Search_onclick = function() {
    if (txb_IsurCd.getValue() != "") {
        scwin.fn_search();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
    }
};
scwin.btn_IsuCdSearch_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;

    //기업인수목적 회사와 주권 목록을 나눔 2010.05.30
    if (scwin.pMenuID == "STF05206") {
        $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
    } else if (scwin.pMenuID == "STF05261") {
        //기업인수목적 회사
        $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
        scwin.spanYN = "Y";
    } else {
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    }

    //fn_PopFindCorpChrg(fr_SecuGrpId);

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Close_onclick = function() {
    window.close();
};
scwin.img_Regist_onclick = function() {
    if (txb_IsurCd.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
        txb_IsurCd.focus();
        return true;
    }
    if (cmb_RegistTyp.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return true;
    }
    scwin.bndYN = scwin.fn_bnd_list_corp_yn();
    if (scwin.bndYN == 'Y' &&
        (cmb_RegistTyp.BindColVal == "0" || cmb_RegistTyp.BindColVal == "2" || cmb_RegistTyp.BindColVal == "6") &&
        scwin.fr_SecuGrpId == 'ST') {
        $c.win.alert($c.stf.getMessageParam("MSG-0027", dts_Corp.getCellData(1, "MEMO_CONTN")));
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(cmb_RegistTyp.BindColVal, "");
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;

    // 거래정지지정및해제구분코드 값 넘겨야함
    scwin.fn_newpre_create_frame(dts_List.getCellData(dts_List.getRowPosition(), "HALT_DESNRELS_TP_CD"), dts_List.getCellData(dts_List.getRowPosition(), "TRD_HALT_STRT_DD"));
};
scwin.rdo_DIRECT_DISCLS_OnSelChange = function() {
    scwin.fn_save_direct_dlscls_onoff();
};
scwin.trs_process_OnSuccess = async function() {
    if (dts_Svcstat.getCellData(1, "SVC_RUN_YN") == 'Y') await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05017.gfm", "알림", 450, 200, 400, 300, "window");

    else if (dts_Svcstat.getCellData(1, "SVC_RUN_YN") == 'N') await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05018.gfm", "알림", 450, 200, 400, 250, "window");
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    if (scwin.fr_SecuGrpId == 'MF') {
        // by nhkw 20181116
        cmb_RegistTyp.CBData = scwin.strCbd_MF;
    }
    scwin.fn_direct_dlscls_status();
};
